PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?earlierFilm ?earlierFilmLabel ?earlierDirector ?earlierDirectorLabel ?birthEarlier ?birthLater WHERE {
  # Get directors
  dbr:Old_Acquaintance dbo:director ?dir1 .
  dbr:Interrupted_Melody dbo:director ?dir2 .

  # director 1 birth date (try dbo:birthDate then dbp:birthDate)
  OPTIONAL { ?dir1 dbo:birthDate ?bd1. }
  OPTIONAL { ?dir1 dbp:birthDate ?bd1_ . }
  BIND(COALESCE(?bd1, ?bd1_) AS ?birth1raw)
  BIND(xsd:date(STR(?birth1raw)) AS ?birth1)

  # director 2 birth date
  OPTIONAL { ?dir2 dbo:birthDate ?bd2. }
  OPTIONAL { ?dir2 dbp:birthDate ?bd2_ . }
  BIND(COALESCE(?bd2, ?bd2_) AS ?birth2raw)
  BIND(xsd:date(STR(?birth2raw)) AS ?birth2)

  # Option A: director of Old Acquaintance born earlier than director of Interrupted Melody
  {
    FILTER(bound(?birth1) && bound(?birth2) && (?birth1 < ?birth2))
    BIND(dbr:Old_Acquaintance AS ?earlierFilm)
    BIND(?dir1 AS ?earlierDirector)
    BIND(?birth1 AS ?birthEarlier)
    BIND(?birth2 AS ?birthLater)
  }
  UNION
  # Option B: director of Interrupted Melody born earlier
  {
    FILTER(bound(?birth1) && bound(?birth2) && (?birth2 < ?birth1))
    BIND(dbr:Interrupted_Melody AS ?earlierFilm)
    BIND(?dir2 AS ?earlierDirector)
    BIND(?birth2 AS ?birthEarlier)
    BIND(?birth1 AS ?birthLater)
  }

  OPTIONAL { ?earlierFilm rdfs:label ?earlierFilmLabel . FILTER(lang(?earlierFilmLabel) = 'en') }
  OPTIONAL { ?earlierDirector rdfs:label ?earlierDirectorLabel . FILTER(lang(?earlierDirectorLabel) = 'en') }
}

